"and",conditions={}},autoResult7={}},znqd5npc12={id="znqd5npc12",baseId="rwnpc2601",combatid={1,1001},name="灵猴",teamMark=-1,canSee=1,caozuoName1="继续聆听",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL灵猴：后来武馆只得改动招式、更换功法名称，在拆解重编的过程中融会贯通。NOR"}},{type="doc",args={"YEL灵猴：招式本就脱胎于各门派，改动途中处处掣肘。少侠，为尊敬先辈，改编他人武学，你是否会保留原名纪念创派先人？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},caozuoName2="饮水思源",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL灵猴：重礼知本，不忘来路，难能可贵。NOR"}},{type="change",args={"znqd5npc12","znqd5npc13"}}},caozuoName3="酌情改动",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL灵猴：权衡利弊，处事圆融，想得十分周全。NOR"}},{type="change",args={"znqd5npc12","znqd5npc13"}}},buttonShow4=1,condition4={relation="and",conditions={}},result4={},buttonShow5=1,condition5={relation="and",conditions={}},result5={},buttonShow6=1,condition6={relation="and",conditions={}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},znqd5npc13={id="znqd5npc13",baseId="rwnpc2601",combatid={1,1001},name="灵猴",teamMark=-1,canSee=1,caozuoName1="继续聆听",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL灵猴：武馆自后尽数吸纳各家武学长处，反自成一派，长久屹立于江湖之中。NOR"}},{type="doc",args={"YEL灵猴：可回想当初，他们擅录各派秘学，引来全江湖追诉问责。少侠你觉得，文墨武馆此举，当真有错吗？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},caozuoName2="有错",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL灵猴：所言有理，取用他人心血，理应先征得应允。NOR"}},{type="change",args={"znqd5npc13","znqd5npc14"}}},caozuoName3="功过相抵",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL灵猴：世事本无绝对对错，利弊相伴，便是江湖常态。NOR"}},{type="change",args={"znqd5npc13","znqd5npc14"}}},buttonShow4=1,condition4={relation="and",conditions={}},result4={},buttonShow5=1,condition5={relation="and",conditions={}},result5={},buttonShow6=1,condition6={relation="and",conditions={}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},znqd5npc14={id="znqd5npc14",baseId="rwnpc2601",combatid={1,1001},name="灵猴",teamMark=-1,canSee=1,caozuoName1="继续聆听",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL灵猴：毕竟这些内门绝学，也是各门各派苦心钻研的成果。但若有协商环境，未必没有两全之法。NOR"}},{type="doc",args={"YEL灵猴：也许若连年以厚礼补偿、诚心相谈，亦有机会互通有无、共享武学。少侠，若是你，你当如何？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},caozuoName2="延续合作",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL灵猴：原来如此。纵使壮士扼腕、忍痛取舍，也想借力诸派，相融共处么？NOR"}},{type="mapstatustags",args={"510014",1}},{type="change",args={"znqd5npc14","znqd5npc15"}}},caozuoName3="别开生面",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL灵猴：哈哈！所言甚是，我的剑也未尝不利，不试试怎知如何！NOR"}},{type="mapstatustags",args={"510014",1}},{type="change",args={"znqd5npc14","znqd5npc15"}}},buttonShow4=1,condition4={relation="and",conditions={}},re